from collections import Counter
from itertools import combinations
from math import log2
from typing import Hashable, Sequence

def entropy_bits(column: Sequence[Hashable]) -> float:
    """Plug-in entropy (bits) of a column observed on a uniform finite sample."""
    n = len(column)
    return -sum(c / n * log2(c / n) for c in Counter(column).values())

def capacity_bits(label: Sequence[Hashable], dials: Sequence[Sequence[Hashable]], subset: Sequence[int]) -> float:
    """cap(S) = H(L) + H(F|S) - H(L, F|S)."""
    reading = [tuple(dials[i][x] for i in sorted(subset)) for x in range(len(label))]
    return entropy_bits(label) + entropy_bits(reading) - entropy_bits(list(zip(label, reading)))

def capacity_lattice(label: Sequence[Hashable], dials: Sequence[Sequence[Hashable]]) -> dict[frozenset[int], float]:
    """Capacity of every sub-battery; O(2^k * N * k)."""
    k = len(dials)
    return {frozenset(S): capacity_bits(label, dials, S) for r in range(k + 1) for S in combinations(range(k), r)}

if __name__ == "__main__":
    pts = [(a, b) for a in (0, 1) for b in (0, 1)]
    L = [a ^ b for a, b in pts]
    lat = capacity_lattice(L, [[a for a, _ in pts], [b for _, b in pts]])
    for S, c in sorted(lat.items(), key=lambda t: len(t[0])):
        print(sorted(S), round(c, 4))

from collections import Counter
from itertools import combinations
from math import log2
from typing import Hashable, Sequence

def _H(col: Sequence[Hashable]) -> float:
    n = len(col)
    return -sum(c / n * log2(c / n) for c in Counter(col).values())

def _cap(L: Sequence[Hashable], F: Sequence[Sequence[Hashable]], S: frozenset[int]) -> float:
    R = [tuple(F[i][x] for i in sorted(S)) for x in range(len(L))]
    return _H(L) + _H(R) - _H(list(zip(L, R)))

def submodularity_witnesses(L: Sequence[Hashable], F: Sequence[Sequence[Hashable]], tol: float = 1e-9) -> list[tuple[frozenset[int], int, int, float]]:
    """All (S, i, j) with positive second difference cap(S+ij) - cap(S+i) - cap(S+j) + cap(S)."""
    k = len(F)
    memo: dict[frozenset[int], float] = {}
    def cap(S: frozenset[int]) -> float:
        if S not in memo:
            memo[S] = _cap(L, F, S)
        return memo[S]
    out = []
    for r in range(k - 1):
        for S0 in combinations(range(k), r):
            S = frozenset(S0)
            rest = [i for i in range(k) if i not in S]
            for i, j in combinations(rest, 2):
                d = cap(S | {i, j}) - cap(S | {i}) - cap(S | {j}) + cap(S)
                if d > tol:
                    out.append((S, i, j, d))
    return out

if __name__ == "__main__":
    pts = [(a, b) for a in (0, 1) for b in (0, 1)]
    print(submodularity_witnesses([a ^ b for a, b in pts], [[a for a, _ in pts], [b for _, b in pts]]))

