"""Synergy sandwich: synergy versus its two bounds over random three-variable distributions."""
import itertools, math, random
import matplotlib.pyplot as plt

def H(p: dict) -> float:
    return -sum(v * math.log2(v) for v in p.values() if v > 0)

def marg(p: dict, idx: tuple) -> dict:
    out: dict = {}
    for k, v in p.items():
        key = tuple(k[i] for i in idx); out[key] = out.get(key, 0.0) + v
    return out

def quantities(p: dict) -> tuple[float, float, float]:
    HL, Hf, Hg = H(marg(p, (0,))), H(marg(p, (1,))), H(marg(p, (2,)))
    HLf, HLg, Hfg, HLfg = H(marg(p, (0, 1))), H(marg(p, (0, 2))), H(marg(p, (1, 2))), H(p)
    Ilf, Ilg, Ilfg = HL + Hf - HLf, HL + Hg - HLg, HL + Hfg - HLfg
    syn = Ilfg - Ilf - Ilg
    return -min(Ilf, Ilg), syn, min(HLf - HL, HLg - HL)

rng = random.Random(0)
lo, sy, hi = [], [], []
for _ in range(4000):
    w = [rng.random() ** rng.choice([1, 3, 8]) for _ in range(8)]
    s = sum(w); p = {k: x / s for k, x in zip(itertools.product([0, 1], repeat=3), w)}
    a, b, c = quantities(p); lo.append(a); sy.append(b); hi.append(c)
xor = {k: (0.25 if k[0] == k[1] ^ k[2] else 0.0) for k in itertools.product([0, 1], repeat=3)}
xa, xs, xh = quantities(xor)
fig, ax = plt.subplots(1, 2, figsize=(12, 5))
ax[0].scatter(hi, sy, s=4, alpha=.4, c="tab:blue"); ax[0].plot([0, 1], [0, 1], "k--", lw=1, label="Syn = upper bound")
ax[0].scatter([xh], [xs], c="red", s=80, marker="*", label="XOR (attains bound)")
ax[0].set_xlabel("min(H(f|L), H(g|L))  [bits]"); ax[0].set_ylabel("Syn  [bits]"); ax[0].set_title("Upper half of the synergy sandwich"); ax[0].legend()
ax[1].scatter(lo, sy, s=4, alpha=.4, c="tab:green"); ax[1].plot([-1, 0], [-1, 0], "k--", lw=1, label="Syn = -min(I(L;f), I(L;g))")
ax[1].set_xlabel("-min(I(L;f), I(L;g))  [bits]"); ax[1].set_ylabel("Syn  [bits]"); ax[1].set_title("Lower half of the synergy sandwich"); ax[1].legend()
