import itertools, math
import matplotlib.pyplot as plt

def H(vals: list) -> float:
    n = len(vals); c: dict = {}
    for v in vals: c[v] = c.get(v, 0) + 1
    return -sum(k / n * math.log2(k / n) for k in c.values())

pts = list(itertools.product([0, 1], repeat=3))
L = [a ^ b for a, b, _ in pts]
F = [[a for a, _, _ in pts], [b for _, b, _ in pts], [(a ^ b) & c for a, b, c in pts]]
def cap(S: tuple) -> float:
    R = [tuple(F[i][x] for i in S) for x in range(len(pts))]
    return H(L) + H(R) - H(list(zip(L, R)))
subsets = [S for r in range(4) for S in itertools.combinations(range(3), r)]
pos = {S: (i - (len([T for T in subsets if len(T) == len(S)]) - 1) / 2, len(S))
       for r in range(4) for i, S in enumerate([T for T in subsets if len(T) == r])}
fig, ax = plt.subplots(figsize=(9, 6))
for S in subsets:
    for T in subsets:
        if len(T) == len(S) + 1 and set(S) <= set(T):
            ax.plot([pos[S][0], pos[T][0]], [pos[S][1], pos[T][1]], "k-", lw=.8, zorder=0)
for S in subsets:
    c = cap(S)
    ax.scatter(*pos[S], s=2200, c=[[1 - .6 * c, 1 - .3 * c, 1]], edgecolors="k", zorder=1)
    ax.text(pos[S][0], pos[S][1], ("{" + ",".join(str(i + 1) for i in S) + "}") + f"\n{c:.3f}", ha="center", va="center", fontsize=9)
ax.set_title("Capacity lattice cap(S) = I(L; F|S) in bits: monotone up every edge,\nbut {1},{2} carry 0 while {1,2} carries 1 bit (not submodular)")
ax.axis("off"); plt.tight_layout(); plt.savefig("lattice.png", dpi=150); print("saved lattice.png")
